def folders = [['identifier':'FSAE2027:SUB:SES','parent':'FSAE2027:SUB:module','title':'FSAE2027:SUB SES Structural Equivalency Spreadsheet (SES) and structural documentation','text':'The Structural Equivalency Spreadsheet (SES) is the SAE-provided Excel workbook (Table PS-1, XLSX, Tech group) in which every team documents its Primary Structure, proves equivalence of any non-baseline material or geometry to the steel-tube baseline, and documents front impact (AIP/IA attachment, with the IAD report attached) and, for EV, the tractive battery container and tractive-system protection. It is uploaded through the team\'s event-website account before the published pre-competition due date (months ahead of the event; the date is set on the website, not in the rules) and reviewed by an assigned SES reviewer whose comments must all be resolved. The approved copy is brought to Technical Inspection. Late upload costs 20 points per day; not submitting is grounds for removal. Model state: only the vehicle-protection slice rules (F.3.2-F.3.5, F.5.1, F.5.6-F.5.9, F.6.4, F.7.5, F.8, V.2.1) are traced to model elements and open verification checks; F.2, F.4, the rest of F.5/F.6/F.7, F.10, F.11 and the PS/IN process rules are not traced yet. An item is \'partial\' when such a trace stands for it. The model holds no dimension, material or test value, so no item is \'present\'. DEC-CHASSIS gates almost every item. Detailed IAD content is left to the IAD list; for F.10 the SES carries the structural proof of the battery container and its attachment (F.10.1.2, F.10.5.1) while the ESF carries the electrical design, so overlapping container items can be deduplicated by that split. The list also covers container openings and positive-locking retention (F.10.4, F.10.2.6, F.10.3.3), physical evidence brought to inspection (IN.6.1, F.10.3.5), and monocoque build evidence for a laminated-in Front Hoop (IN.6.3.2-IN.6.3.3).','derive':['TABLE-PS-1:p002'],'satisfy':['OA|OperationalActivity|FSAE2027:process Prepare and document competition entry'],'attributes':['submission_id':'SES','submission_governing_rules':'["F.2.1 (FSAE-2027-V1:F.2.1.1:p001, F.2.1.2:p002-p004): the SES documents the Primary Structure, establishes equivalence and lets reviewers flag other concerns","F.2.2 (F.2.2.1:p001, F.2.2.2:p001): every team submits an SES and must close all reviewer comments","F.2.3 (F.2.3.1-F.2.3.3): equivalence uses SES methods against steel tubing in the same application; tubes and laminates may be combined","F.2.4 / F.2.5: tolerances handled in the SES; the car must be built as documented","PS.2.2 + TABLE-PS-1:p002: SES is an XLSX on the event template, Tech penalty group; TABLE-PS-2:p003 20 points per 24 h late, removal if not submitted (PS.3.3)","F.3.2.1 / F.3.4.1: application-to-size-class table (sizes A-D); fixed in the SES, not team inputs","F.3.4.2 / F.3.5.3: prescribed steel and 6061-T6 reference properties (welded and non-welded) used by the SES; not team inputs","F.3.5, F.4.1-F.4.4: alternative tubing and composite evidence and test methods","F.5.1-F.5.16, F.6.1-F.6.6, F.7.1-F.7.9: chassis, tube-frame and monocoque geometry/attachment rules evidenced in the SES","F.8.2.3, F.8.5.1, F.8.8.1: AIP and IA attachment plus the IAD report are part of the SES","F.10.1.2, F.10.1.3, F.10.5.1, F.11: battery container design/attachment and tractive-system protection are reviewed through the SES","EV.5.1.3, IN.6.1: battery hardware must match the SES; SES copy at technical inspection","F.10.4, F.10.2.6, F.10.3.3, F.10.1.6: container openings, positive locking of lids and module mounts, rivet guidance; part of the container design reviewed through the SES (F.10.1.3)","IN.6.1 (p006), IN.6.3.2-IN.6.3.3, F.10.3.5 (p004): laminate specimens, tested module structure and monocoque build evidence presented at Technical Inspection"]','submission_format':'XLSX','submission_penalty_group':'Tech','submission_status':'not_started','submission_due':'TBD','submission_cancellation':'TBD']],['identifier':'FSAE2027:SUB:SES:ADM','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-ADM Submission administration','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:TUB','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-TUB Tubing application and steel material','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:ALU','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-ALU Aluminum tubing (conditional)','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:CMP','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-CMP Composite and other materials (conditional)','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:JNT','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-JNT Joints, bends and connections','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:HOP','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-HOP Roll hoops and driver envelope','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:FBH','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-FBH Front bulkhead and support','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:SIS','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-SIS Side impact structure','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:HAR','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-HAR Shoulder harness and harness attachment','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:MON','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-MON Monocoque construction and attachments (conditional)','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:FRT','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-FRT Front impact protection documented in the SES','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:SES:EV','parent':'FSAE2027:SUB:SES','title':'FSAE2027:SUB SES-EV EV tractive battery container and tractive system protection','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'SES']],['identifier':'FSAE2027:SUB:IAD','parent':'FSAE2027:SUB:module','title':'FSAE2027:SUB IAD Impact Attenuator Data (IAD) report - section of the Structural Equivalency Spreadsheet (SES)','text':'The IAD is not a standalone upload: F.8.8.1 makes it part of the SES. The SES is a single XLSX file built on the event-provided template with its format left unchanged (FSAE-2027-V1:TABLE-PS-1:p002 and p014, PS.2.2.1-PS.2.2.4). North American teams upload it through their own team login on the Event Website before the published Due Date; a later Cancellation Date is the last chance to upload (PS.1.1.1, PS.1.2.2, PS.1.2.3, PS.2.1). It is a pre-competition submission and the rulebook does not fix the date. Each submission is reviewed by an assigned event official (PS.1.2.8). Every SES reviewer comment must be resolved (F.2.2.2), and a requested revision can carry its own new deadline (PS.3.1.3). The SES sits in the Tech penalty group: -20 points per 24 h late, and a missing SES after the Cancellation Date is grounds for removing the team entry (FSAE-2027-V1:TABLE-PS-2:p003, PS.1.2.7, PS.3.3.1). A file in the wrong format or largely incomplete counts as not submitted (PS.1.2.5), and teams are not told if an upload is wrong (PS.3.1.4). Because the upload is one file, photos, test data and calculations must live inside that workbook or be referenced from it (an inference from PS.2.2.4). Content depends on the attenuator route. With an approved Standard IA no test data is sent, but photos of the real part, supplier evidence against the Standard IA specification and the remaining requirements of the section are still due (F.8.8.3; the rule says \'this section\' without naming F.8 or F.8.8). A Custom IA needs test data, derivation calculations, a test schematic and photos annotated with heights before and after the test (F.8.8.4), under the validity, setup, conduct and analysis rules of F.8.8.5-F.8.8.8. The SES (not necessarily the IAD tab) must also document the AIP-to-bulkhead and IA attachment methods (F.8.2.3, F.8.5.1), and the front-object and combined-force evidence of F.8.6-F.8.7 belongs in the same front-chassis review. At Technical Inspection the team brings the electronic SES and, when applicable, the tested attenuator and any laminate test specimens (IN.6.1). The car must be built as the SES describes it (F.2.5). Model state: none of the 135 F.8 rule paragraphs is traced directly. The vehicle-protection slice restates them as FSAE2027:VP:obligation:* requirements, which have a candidate owner but no design choice and no verification. The model has no separate IA, AIP or Front Bulkhead element. The whole front stack is one lumped candidate, \'FSAE2027:VP Attenuator anti-intrusion and front load paths\' (Equipment / Physical behavior / Logical subsystem / CI). No element carries property values, and the only LiteralNumericValues are predefined datatype bounds. Rule thresholds exist only as text in those obligations, so items that only restate a rule value are \'partial\', not \'present\'. None of the 8 DEC-* decisions covers standard-vs-custom IA or AIP material/attachment, so those choices have no DEC id; they appear only as \'Open choices\' text in the VP verification constraints.','derive':['F.8.8.1:p001'],'satisfy':['OA|OperationalActivity|FSAE2027:process Prepare and document competition entry'],'attributes':['submission_id':'IAD','submission_governing_rules':'["F.8.8.1: the IAD report is part of the SES, not a separate upload","F.8.8.2: functional targets, not test criteria: deceleration within 20 g average and 40 g peak and more than 7350 J absorbed, for 300 kg at 7.0 m/s","F.8.8.3: Standard IA: no test data; photos of the real unit and supplier proof (receipt or packing slip) against the Standard IA specification; the rest of the section still applies","F.8.8.4: Custom IA: test data against F.8.8.2, derivation calculations, a test schematic and photos showing the height before and after the test","F.8.8.5: a test result is valid for one competition year","F.8.8.6: test setup: the car\'s IA-to-AIP joint, a representative chassis section as fixture, 50 mm free space behind the AIP, at most 25 mm permanent AIP deflection","F.8.8.7: composite IAs need a dynamic test at a supervised dedicated facility; other IAs may also be tested quasi-statically on university equipment","F.8.8.8: average deceleration from raw unfiltered data; CFC 60 or a 100 Hz Butterworth filter is allowed when peaks pass 40 g","F.8.1.1-F.8.1.2: IA ahead of the Front Bulkhead with the AIP between them; both joints carry off-axis loads","F.8.2.1-F.8.2.3: AIP of 1.5 mm steel, 4.0 mm aluminum or composite; its outline depends on the joint type; the AIP-to-bulkhead joint is documented in the SES","F.8.3.1-F.8.3.2: a composite AIP survives a frontal impact and holds 120 kN over the minimum IA footprint, shown by a representative test or by laminate tests and calculation","F.8.4.1-F.8.4.3: use an approved Standard IA or build and test a Custom IA with minimum size; a large bulkhead or the Standard Honeycomb needs a diagonal brace or a deflection test","F.8.5.1-F.8.5.7: IA joint documented in the SES; allowed joint per IA type; bond, weld and bolt limits; mounting height, centering and orientation","F.8.6.1-F.8.6.3: only the IA, fastener heads and light bodywork ahead of the AIP; front wing and tab limits; 25 mm pedal clearance to the AIP, bulkhead and non-crushable items","F.8.7.1-F.8.7.5: IA plus the force to crush other front objects stays under the F.8.8.2 peak, using the IA peak-load list and a test or a calculation","F.1.8, F.1.9: definitions of Front Bulkhead and Impact Attenuator","F.2.1, F.2.2.1-F.2.2.2, F.2.3.1, F.2.5: the SES is required, reviewer comments must be closed, equivalence uses SES methods, and the car is built as the SES says","F.3.2.1, F.6.1, F.6.4.5, F.7.2, F.7.2.3: Front Bulkhead tube size and Lower Side Impact member for a tube frame; bulkhead shear strength under the AIP for a monocoque","F.4.2.2, F.4.2.5: laminate bend and perimeter-shear tests used by the composite AIP calculation route","F.5.5.1-F.5.5.3: bonded joints: an adhesive suited to both surfaces, its record in the SES, and the SES halving of adhesive values","T.8.2.1: grade of critical fasteners in bolted IA and AIP joints","IN.6.1: bring the electronic SES, and laminate specimens if used, to Technical Inspection","PS.1.1.1, PS.1.2.1-PS.1.2.8: posted deadlines and the meaning of due date, cancellation date, late, not submitted, days late, removal grounds and Reviewer","PS.2.1, PS.2.2.1-PS.2.2.4, TABLE-PS-1:p002, p014: upload to the team account as one XLSX on the unchanged event template","PS.3.1.1-PS.3.1.4, PS.3.2.1-PS.3.2.2, PS.3.3.1, TABLE-PS-2:p003: the team checks its own upload; revisions can bring new deadlines; Tech group, -20 points per day late; a missing SES is grounds for removal"]','submission_format':'XLSX (part of the SES workbook)','submission_penalty_group':'Tech','submission_status':'not_started','submission_due':'TBD','submission_cancellation':'TBD']],['identifier':'FSAE2027:SUB:IAD:ADM','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-ADM Submission and format','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:SEL','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-SEL Attenuator route selection','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:AIP','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-AIP Anti Intrusion Plate','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:ATT','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-ATT IA attachment','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:POS','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-POS IA position and orientation','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:FRT','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-FRT Front objects and pedal clearance','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:FRC','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-FRC Combined frontal force','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:FUN','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-FUN Functional reference','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:RPT','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-RPT Custom IA report contents','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:SET','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-SET Test setup','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:CON','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-CON Test conduct','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:IAD:ANA','parent':'FSAE2027:SUB:IAD','title':'FSAE2027:SUB IAD-ANA Test analysis','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'IAD']],['identifier':'FSAE2027:SUB:ESF','parent':'FSAE2027:SUB:module','title':'FSAE2027:SUB ESF Electrical System Form (ESF)','text':'The ESF is the EV-only technical document in which the team describes the complete vehicle electrical system (tractive system, GLV and control) in a structured way (EV.2.1.1). It is filed before the competition on the official SAE-supplied XLSX template, with the format unchanged, as a single file uploaded through the team\'s Event Website account by the posted due date (EV.2.1.3, PS.2, TABLE-PS-1:p006). An event official assigned as Reviewer checks and accepts it. Reviewers may ask for revisions with new deadlines (PS.1.2.8, PS.3.1.3). The ESO/ESA form (the Electrical System Officer and Advisor details, PDF, Tech group) is a separate upload with the same removal risk; it is tracked as GEN-PS1-02 on the general page. Before upload, the team\'s Electrical System Advisor must review it (AD.5.3.6). It is in the Tech penalty group: -20 points per 24 h late, and if it is still missing at the cancellation date, that is grounds for removing the entry (EV.2.2, TABLE-PS-2:p003, PS.3.3.1). Approval does not guarantee passing inspection (EV.2.1.1:p002). A copy plus component datasheets must be brought to accumulator and charger inspection (IN.5.1:p006), and the built pack and spares must match it (EV.5.1.3). The rulebook names only two content items as ESF-specific: BMS module-boundary isolation (EV.8.3.2) and pack configuration identity (EV.5.1.3). The rest of this list is derived from the EV and T rules the form must describe. The tab layout of the 2027 workbook is not public without a team login, so the section headings here are our own, not the template\'s. FSAE-2027-V1 has no general FMEA requirement. Failure-mode write-ups appear only for digital APPS/BSE transmission and are tied to the ETC Systems Form (T.4.2.11:p002, T.4.3.5:p002, IC.4.4.9). T.4.3.5:p002 is not marked IC-only, so an EV team that sends the BSE signal over a bus should confirm through a Rules Question where to document it.','derive':['TABLE-PS-1:p006'],'satisfy':['OA|OperationalActivity|FSAE2027:process Prepare and document competition entry'],'attributes':['submission_id':'ESF','submission_governing_rules':'["EV.2.1.1 - every team submits an ESF giving clearly structured documentation of the full electrical system, TS and control included; approval does not mean the car passes inspection","EV.2.1.2 - the ESF may carry guidance or detail beyond the rulebook","EV.2.1.3 - use the provided format and submit per section PS","EV.2.2 - ESF penalties follow section PS","TABLE-PS-1:p006 / TABLE-PS-1:p014 - ESF: XLSX, Tech penalty group, use the Event Website template","TABLE-PS-2:p003 - Tech group: -20 points per 24 h late; missing after the deadline is grounds for removal","PS.1.1.1, PS.1.2.2-PS.1.2.8 - due date, cancellation date, late, not-submitted, removal and Reviewer definitions","PS.2.1, PS.2.2.1-PS.2.2.4 - upload to team account; template format unaltered; one file","PS.3.1.1-PS.3.1.4, PS.3.2.1-PS.3.2.3, PS.3.3.1-PS.3.3.2 - team responsibility, revision requests, penalties and entry removal","AD.5.3.6 - ESA reviews the ESF and confirms sound engineering practice in principle; AD.5.3.7 - ESA makes sure unusual design aspects are communicated","IN.5.1:p006 - ESF and component datasheets brought to accumulator/charger inspection","EV.5.1.3 - pack components, containers and spares identical to the design in the ESF and SES","EV.8.3.2 - BMS galvanic isolation at module boundaries is approved through the ESF","Content rules described by the form: EV.1, EV.3-EV.10, T.3.3, T.4.2, T.4.3, T.5.3, T.9.1-T.9.4, IN.10 (expected test results); F.10 and F.11 by cross-reference to the SES"]','submission_format':'XLSX','submission_penalty_group':'Tech','submission_status':'not_started','submission_due':'TBD','submission_cancellation':'TBD']],['identifier':'FSAE2027:SUB:ESF:ADM','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-ADM Administration','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:SYS','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-SYS System overview','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:ACC','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-ACC Accumulator cells and modules','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:CON','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-CON Accumulator container','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:IRP','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-IRP Isolation relays, precharge, discharge and MSD','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:BMS','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-BMS Battery management system','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:TS','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-TS Motors, motor controller and energy meter','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:WIR','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-WIR TS wiring, connectors, insulation and separation','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:OCP','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-OCP Overcurrent protection','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:GND','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-GND Grounding','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:SDC','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-SDC Shutdown circuit','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:IMD','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-IMD Insulation monitoring device','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:BSPD','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-BSPD Brake system plausibility device','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:DD','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-DD APPS, BSE and plausibility','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:IND','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-IND Status indicators and lamp check','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:MP','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-MP Measuring points','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:GLV','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-GLV GLV system','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:CHG','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-CHG Charging','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:ESF:OPS','parent':'FSAE2027:SUB:ESF','title':'FSAE2027:SUB ESF-OPS Activation and ready to drive','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'ESF']],['identifier':'FSAE2027:SUB:DES','parent':'FSAE2027:SUB:module','title':'FSAE2027:SUB DES Design Event documents (Design Briefing, Design Spec Sheet, Vehicle Drawings) - S.4.2 to S.4.5, with S.4.6 to S.4.9 event-day evidence','text':'The Design Event (150 of the 325 static points, S.1:p003, S.4.10.1) needs three documents uploaded before the event: a Design Briefing (PDF, on the official event template), a Design Spec Sheet (XLSX, on the provided format) and three-view Vehicle Drawings (PDF, no template; layout set by S.4.4.1). See S.4.2.1, S.4.3, S.4.4, S.4.5 and Table PS-1 rows p011-p013. The Design Judges review them before the event and use them to sort teams into design groups (S.4.2.2). Judges may also give part of the Design score to the documents themselves (S.4.9.2). Each document is uploaded as a single file into the team\'s own account on the Event Website by the due date posted there; the briefing and spec sheet must use the official templates with their format left unchanged (PS.1.1.1, PS.2.1, PS.2.2.1-PS.2.2.4). A file in the wrong form or format counts as Not Submitted (PS.1.2.5). A late upload costs 20 points for each day late in the \'Other\' penalty group. A document still missing after the cancellation date means removal from the Design event with zero points (S.4.2.3, PS.3.2.1, PS.3.2.2, Table PS-2:p004, S.4.10.3). At the event the judges score from these documents, a conversation with team members and their own look over the finished car (S.4.9.1). The car must arrive fully built, and its tractive battery pack must already have passed inspection (S.4.6.2, IN.5.3). Rulebook S.4.3.2 hands the briefing\'s detailed content and per-topic slide limits to the template. Public FSAE Michigan guidance from fsaeonline.com describes the spec sheet as a two-page subsystem specification spreadsheet. It describes the briefing as a technical design-review document that judges scan across subsystems. Neither official template is reproduced here, so the briefing sections and spec-sheet fields below are derived from the rulebook\'s numeric limits and that public guidance. Confirm them against the 2027 templates on the Event Website. Model state: the S.4, PS.2.2, IN.5.3 and Table PS-1 design rows are in the model, but nothing in S.4 is traced to a design element yet. The model holds no numeric property values.','derive':['TABLE-PS-1:p011','TABLE-PS-1:p012','TABLE-PS-1:p013'],'satisfy':['OA|OperationalActivity|FSAE2027:process Prepare and document competition entry'],'attributes':['submission_id':'DES','submission_governing_rules':'["S.1 (static event points: Design 150)","S.4.1.1-S.4.1.3 (what the judges assess: engineering effort, meeting the design goals at good value, and how bought-in items were chosen and applied)","S.4.2.1 (three Design Documents required)","S.4.2.2 (judges review the documents before the event and use them to group teams)","S.4.2.3 (late penalties come from section PS)","S.4.2.4 (documents that are not a serious effort can lead to exclusion or a lower score)","S.4.3.1-S.4.3.3 (Design Briefing must use the event template, which sets content areas and slide limits per topic)","S.4.4.1-S.4.4.2 (Vehicle Drawings: front, top and side line views, each on its own page, by hand or CAD)","S.4.5 (Design Spec Sheet on the provided format; ranges are allowed for values that will be tuned)","S.4.6.1-S.4.6.2 (full Inspection Approval is not needed before judging; car presented complete; EV battery pack must have passed inspection; unfinished cars are not judged; preparation faults can cost points)","S.4.7.1-S.4.7.2 (optional support material; space at the event may be limited)","S.4.8 (judging may run in rounds, such as a first round and then finals)","S.4.9.1-S.4.9.3 (judging inputs are the documents, a discussion and a vehicle inspection; points are deducted if the team cannot explain the car; score sheets are on the Event Website)","S.4.10.1-S.4.10.3 (0-150 points; penalties; excluded teams score zero)","PS.1.1.1-PS.1.1.2, PS.1.2.1-PS.1.2.6 (due date, cancellation date, late and not-submitted definitions including wrong format, days-late rounding)","PS.2.1, PS.2.2, PS.2.2.1-PS.2.2.4 (upload location, required templates from the Event Website, no format changes, one file per submission, PDF or XLSX)","PS.3.1.1-PS.3.1.4, PS.3.2.1-PS.3.2.3, PS.3.3.1 (team confirms its own upload, free replacement before the due date, revision deadlines, penalties, removal of entry for ignoring reviewer requests)","Table PS-1 rows FSAE-2027-V1:TABLE-PS-1:p011 (Design Briefing, PDF, template), p012 (Vehicle Drawings, PDF), p013 (Design Spec Sheet, XLSX, template), p014 (template note)","Table PS-2 row FSAE-2027-V1:TABLE-PS-2:p004 (Other group: daily late penalty; removal from Design with zero points if not submitted)","IN.5.3 (the tractive battery pack, fitted or loose, may not appear at a static event until its inspection is fully done)","Rules that bound Design Spec Sheet values: V.1.2 wheelbase minimum, V.1.3.1-V.1.3.2 track and rollover stability, ratio of smaller to larger track, V.1.4.1-V.1.4.2 ground clearance and lower side impact structure height, V.3.1.1 minimum wheel travel, V.4.1 minimum wheel diameter, V.4.3 tires, EV.3.3.1 80 kW energy-meter power cap, EV.3.3.2 600 V DC voltage cap, EV.3.3.3 no regeneration from 0 to 5 km/h, EV.4.1-EV.4.2 motors and controller, EV.5 energy storage, T.3 brakes, T.7 aero devices, F.3-F.8 chassis materials, structure and front protection"]','submission_format':'PDF briefing, XLSX spec sheet, PDF drawings','submission_penalty_group':'Other','submission_status':'not_started','submission_due':'TBD','submission_cancellation':'TBD']],['identifier':'FSAE2027:SUB:DES:ADM','parent':'FSAE2027:SUB:DES','title':'FSAE2027:SUB DES-ADM Submission mechanics','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'DES']],['identifier':'FSAE2027:SUB:DES:DB','parent':'FSAE2027:SUB:DES','title':'FSAE2027:SUB DES-DB Design Briefing','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'DES']],['identifier':'FSAE2027:SUB:DES:DSS','parent':'FSAE2027:SUB:DES','title':'FSAE2027:SUB DES-DSS Design Spec Sheet','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'DES']],['identifier':'FSAE2027:SUB:DES:DRW','parent':'FSAE2027:SUB:DES','title':'FSAE2027:SUB DES-DRW Vehicle Drawings','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'DES']],['identifier':'FSAE2027:SUB:DES:EVT','parent':'FSAE2027:SUB:DES','title':'FSAE2027:SUB DES-EVT Event-day readiness','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'DES']],['identifier':'FSAE2027:SUB:COST','parent':'FSAE2027:SUB:module','title':'FSAE2027:SUB COST Cost Report (Cost and Manufacturing Event, with its Cost Addendum and Cost Scenario companions)','text':'The Cost Report is the team\'s priced bill of materials for the whole prototype. It is built and uploaded in the Event Website\'s cost tool, in whatever form that site specifies (Table PS-1 note 2), and it is due before the competition at the Due Date posted on the Event Website. The Cost Event is worth 100 points in total (S.3.16.2), and the Cost Judges assess the report against the car at the competition (S.3.13.4). At the competition the judges hold a discussion beside the car, comparing the report with the vehicle as presented and judging whether the car could be manufactured. Teams may also be picked for a Cost Audit. Table PS-1 puts the Cost Report in penalty group Other. Under Table PS-2 that means -20 points for each 24 hours late, with any part of a day counted as a full day. A report not submitted by the Cancellation Date removes the team from the Cost event with a score of zero. Every price must come from the official Cost Tables, built up by vehicle, then system, then assembly, then part, then material, process, fastener and tooling. The Cost Event Supplement on the Event Website carries the detailed costing guidance (S.3.2); the public Supplement is where the system categories and tooling method are defined. Two related deliverables follow. The Cost Addendum is handed in at onsite registration on a template and covers changes made after submission. The Cost Scenario submission is required only if that year\'s scenario document asks for it, and Table PS-1 also puts it in penalty group Other. Penalties work two ways. Method A deducts a fixed number of points per omission. Method B adds twice the understated amount to the Adjusted Cost. Whichever is larger applies. The model already has the vehicle-to-subsystem-to-CI tree (EPBS) and a physical-node tree (PA). It holds no cost, material, process, fastener, tooling, make/buy or quantity data. None of the 90 S.1/S.3 rule paragraphs, the 53 PS paragraphs or the 19 Table PS-1/PS-2 rows is traced to a model element yet.','derive':['TABLE-PS-1:p008','TABLE-PS-1:p009','TABLE-PS-1:p010'],'satisfy':['OA|OperationalActivity|FSAE2027:process Prepare and document competition entry'],'attributes':['submission_id':'COST','submission_governing_rules':'["S.1 (static event points: Cost worth 100) FSAE-2027-V1:S.1:p002","S.3.1 Cost Event Objective FSAE-2027-V1:S.3.1:p001-p002","S.3.2 Cost Event Supplement FSAE-2027-V1:S.3.2:p001-p003","S.3.3 Cost Event Areas (report, event-day discussion, scenario) FSAE-2027-V1:S.3.3.1:p001-S.3.3.3:p002","S.3.4 Cost Report content and submission FSAE-2027-V1:S.3.4.1:p001-p007, S.3.4.2:p001","S.3.5 Bill of Materials hierarchy FSAE-2027-V1:S.3.5.1:p001-p006","S.3.6 Late Submission FSAE-2027-V1:S.3.6:p001","S.3.7 Cost Addendum FSAE-2027-V1:S.3.7.1:p001-S.3.7.6:p003","S.3.8 Cost Tables FSAE-2027-V1:S.3.8.1:p001, S.3.8.2:p001","S.3.9 Make versus Buy FSAE-2027-V1:S.3.9.1:p001-S.3.9.4:p001","S.3.10 Add Item Request FSAE-2027-V1:S.3.10.1:p001, S.3.10.2:p001","S.3.11 Public Cost Reports FSAE-2027-V1:S.3.11.1:p001, S.3.11.2:p001","S.3.12 Cost Report Penalties Process (Method A fixed points, Method B adjusted cost) FSAE-2027-V1:S.3.12.1:p001-S.3.12.5:p005","S.3.13 Event Day and Discussion FSAE-2027-V1:S.3.13.1:p001-S.3.13.4:p005","S.3.14 Cost Audit FSAE-2027-V1:S.3.14.1:p001, S.3.14.2:p001","S.3.15 Cost Scenario FSAE-2027-V1:S.3.15.1:p001-S.3.15.5:p001","S.3.16 Cost Event Scoring FSAE-2027-V1:S.3.16.1:p001-S.3.16.4:p001","PS.1.1 documents due by posted deadlines, procedures on Event Website FSAE-2027-V1:PS.1.1.1:p001, PS.1.1.2:p001","PS.1.2 submission definitions (Submission Date, Due Date, Cancellation Date, Late Submission, Not Submitted, Amount Late, Grounds for Removal, Reviewer) FSAE-2027-V1:PS.1.2.1:p001-PS.1.2.8:p002","PS.2.1 / PS.2.2 submission location, template use and single-file format FSAE-2027-V1:PS.2.1:p001, PS.2.2:p001-PS.2.2.4:p001","PS.3.1-PS.3.3 team responsibility, penalties, removal FSAE-2027-V1:PS.3.1.1:p001-PS.3.3.2:p003","Table PS-1 rows FSAE-2027-V1:TABLE-PS-1:p008 (Cost Report: S.3.4, form per S.3.4.2, file format per note 2, group Other), p009 (Cost Addendum: S.3.7, template per note 1, group none), p010 (Cost scenario deliverable, only when S.3.15.3 calls for it: group Other), p014-p015 (notes 1 and 2)","Table PS-2 group Other FSAE-2027-V1:TABLE-PS-2:p004 (-20 points per 24 h late; not submitted -> removed from the Cost event with zero score, per PS.3.2.2)","Formula SAE Cost Event Supplement (Event Website, external official document; sets BOM format, system categories, tooling and costing method)"]','submission_format':'Event Website cost tool','submission_penalty_group':'Other','submission_status':'not_started','submission_due':'TBD','submission_cancellation':'TBD']],['identifier':'FSAE2027:SUB:COST:ADM','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-ADM Submission administration','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:COST:TRC','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-TRC Rule traceability','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:COST:BOM','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-BOM BOM structure','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:COST:CT','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-CT Costing from Cost Tables','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:COST:MB','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-MB Make versus buy','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:COST:DOC','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-DOC Supporting documentation','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:COST:PEN','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-PEN Penalty self-check','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:COST:ADD','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-ADD Cost Addendum','text':'','derive':[],'satisfy':['OA|OperationalActivity|FSAE2027:process Inspect and present the vehicle'],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:COST:SCN','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-SCN Cost Scenario','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:COST:EVT','parent':'FSAE2027:SUB:COST','title':'FSAE2027:SUB COST-EVT Event day and audit','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'COST']],['identifier':'FSAE2027:SUB:PRES','parent':'FSAE2027:SUB:module','title':'FSAE2027:SUB PRES Presentation Event (Business Presentation) pre-event submission, Table PS-1 row "Presentation (if required)", S.2.4','text':'The Presentation Event is a 75-point static event (S.1:p001). The team pitches a business, logistics, production or technical case for its car to a judging panel that is not all engineers (S.2.1, S.2.2.5). The rulebook does not set what the submission contains. Under S.2.4.1 and Table PS-1 row p007, a pre-event submission exists only if that year\'s Presentation Concept asks for one. The Concept is published on the Event Website (fsaeonline.com, Series Resources) and may change for each competition (S.2.2.1, S.2.2.2). It sets the content, file format, due date and any extra penalties (S.2.4.1, S.2.4.3). Any submission is uploaded to the team account before the Due Date by a Team Member or Team Captain. Late or missing uploads are penalised under the PS rules, in Table PS-2 group "Other". The penalty is -20 points for each 24 hours late, with any part of a day counting as a full day, applied with official discretion (PS.3.2.1, PS.1.2.6). A Not Submitted document removes the team from the event with a score of zero (PS.3.2.2, TABLE-PS-2:p004). The Concept may set different penalties (S.2.4.3). Judges may include the submission in the event score (S.2.4.2). At the event, the team presents live in its assigned slot, and the judges then ask questions (S.2.3, S.2.5). The 2027 Concept was not available for this research, so every content item is marked as defined by the Concept and still to be determined. Background material found on the web (older event guides and team pages) is not authoritative and has not been used as fact. Model state: the S.1, S.2, PS and Table PS-1/PS-2 rule paragraphs are in the model but not traced to any element. It also holds two operational activities owned by Team personnel, "FSAE2027:process Prepare and document competition entry" and "FSAE2027:process Inspect and present the vehicle". Each is only a name, with no description, exchanges, capability involvement or requirement links. The only content the model can supply is a description of the vehicle as entered (S.2.2.4), drawn from SA, LA, PA and EPBS. Its specifications are TBD because the DEC-* decisions are still open. No item is fully present in the model. The six vehicle-content items are partial: their anchor elements exist by name but carry no description or values, and the values wait on the DEC-* decisions. Every other item is absent. The model treats competition administration as a team process, so the two process activities are the anchors.','derive':['TABLE-PS-1:p007'],'satisfy':['OA|OperationalActivity|FSAE2027:process Prepare and document competition entry'],'attributes':['submission_id':'PRES','submission_governing_rules':'["S.1 (FSAE-2027-V1:S.1:p001) - Presentation event point value 75","S.2.1 (FSAE-2027-V1:S.2.1:p001) - event objective: business/logistics/production/technical case aimed at outside investors","S.2.2.1-S.2.2.6 (FSAE-2027-V1:S.2.2.1:p001 .. S.2.2.6:p002) - Presentation Concept published on Event Website, may change per competition, must be met, must relate to the vehicle as entered, mixed-discipline judges, setting may vary","S.2.3 (FSAE-2027-V1:S.2.3:p001) - missing the assigned slot scores zero","S.2.4.1-S.2.4.3 (FSAE-2027-V1:S.2.4.1:p001, S.2.4.2:p001, S.2.4.3:p001) - pre-event submission if the Concept requires it, may be graded, penalties under PS or the Concept","S.2.5.1-S.2.5.5 (FSAE-2027-V1:S.2.5.1:p001 .. S.2.5.5:p001) - presenters, presence and introduction, time limit, Q&A after presentation, only qualified members answer","S.2.6 (FSAE-2027-V1:S.2.6:p001) - equipment per the Concept","S.2.7.1-S.2.7.3 (FSAE-2027-V1:S.2.7.1:p001 .. S.2.7.3:p001) - evaluation criteria, prototype quality not judged, official score sheet on Event Website","S.2.8 (FSAE-2027-V1:S.2.8:p001) - judging may be in several phases","S.2.9.1-S.2.9.3 (FSAE-2027-V1:S.2.9.1:p001 .. S.2.9.3:p001) - averaged judge scores, 0-75 range, normalisation/scaling","PS.1.1.1-PS.1.2.8 - submission deadlines, published procedures, and definitions (Submission/Due/Cancellation Date, Late, Not Submitted, Amount Late, Grounds for Removal, Reviewer)","PS.2.1, PS.2.2, PS.2.2.1-PS.2.2.4 - upload to team account, Table PS-1, templates, single file in specified format","PS.3.1.1-PS.3.1.4 - team confirms its own upload; uploads can be replaced without penalty before the Due Date; Reviewer may ask for a revision with a new deadline; no notice is given of an incorrect submission","PS.3.2.1-PS.3.2.3, PS.3.3.1-PS.3.3.2 - late/not-submitted penalties and removal","TABLE-PS-1 (FSAE-2027-V1:TABLE-PS-1:p007) - Presentation row: requirement, format and file type all point to S.2.4; penalty group Other. Footnotes p014 (template) and p015 (Event Website requirements) are not attached to this row","TABLE-PS-2 (FSAE-2027-V1:TABLE-PS-2:p004) - group Other: -20 points per 24 hours late; Not Submitted means removal from the Cost/Design/Presentation event with a score of 0 (see PS.3.2.2)","AD.1.3 (FSAE-2027-V1:AD.1.3:p001, p002) - English is the series language and is accepted for submissions and presentations","AD.2.1.1-AD.2.1.4 - Event Website Series Resources, team account, Team Captain, only Team Members/Captains upload","AD.5.1.3 (FSAE-2027-V1:AD.5.1.3:p004) - Faculty Advisor must not develop documentation or presentation"]','submission_format':'TBD (set by the Presentation Concept)','submission_penalty_group':'Other','submission_status':'not_started','submission_due':'TBD','submission_cancellation':'TBD']],['identifier':'FSAE2027:SUB:PRES:ADM','parent':'FSAE2027:SUB:PRES','title':'FSAE2027:SUB PRES-ADM Presentation Concept intake','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'PRES']],['identifier':'FSAE2027:SUB:PRES:SUB','parent':'FSAE2027:SUB:PRES','title':'FSAE2027:SUB PRES-SUB Pre-event submission package','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'PRES']],['identifier':'FSAE2027:SUB:PRES:DL','parent':'FSAE2027:SUB:PRES','title':'FSAE2027:SUB PRES-DL Deadlines and upload','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'PRES']],['identifier':'FSAE2027:SUB:PRES:VEH','parent':'FSAE2027:SUB:PRES','title':'FSAE2027:SUB PRES-VEH Vehicle-as-entered content','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'PRES']],['identifier':'FSAE2027:SUB:PRES:CASE','parent':'FSAE2027:SUB:PRES','title':'FSAE2027:SUB PRES-CASE Case content and audience','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'PRES']],['identifier':'FSAE2027:SUB:PRES:LOG','parent':'FSAE2027:SUB:PRES','title':'FSAE2027:SUB PRES-LOG Delivery logistics','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'PRES']],['identifier':'FSAE2027:SUB:PRES:SCR','parent':'FSAE2027:SUB:PRES','title':'FSAE2027:SUB PRES-SCR Scoring record','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'PRES']],['identifier':'FSAE2027:SUB:PRES:TRC','parent':'FSAE2027:SUB:PRES','title':'FSAE2027:SUB PRES-TRC Model traceability','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'PRES']],['identifier':'FSAE2027:SUB:GEN','parent':'FSAE2027:SUB:module','title':'FSAE2027:SUB GEN General submission rules (PS.1-PS.3 and cross-cutting admin rules): location, format, deadlines, penalties','text':'This is the cross-cutting layer that applies to every pre-competition document, not a single deliverable. Table PS-1 lists the documents: SES, ESO/ESA form, ESF, Design Briefing, Vehicle Drawings, Design Spec Sheet, Cost Report, Cost Addendum, the Presentation and Cost Scenario pre-event items (only if the Presentation Concept or Cost Scenario asks for them), and the IC-only ETC forms. Only a Team Captain or an accepted Team Member may upload, into the team\'s own account on the Event Website (fsaeonline.com). Most documents go up as one PDF or XLSX file, and the ones Table PS-1 marks with note (1) must use the unmodified official template. There are exceptions. The Cost Report is generated inside the Event Website. The Cost Addendum is handed in at onsite registration. The Presentation and Cost Scenario items take their format from the Concept or Scenario document. Each document has its own Due Date and Cancellation Date. These are set on the live Event Website deadlines page (https://www.fsaeonline.com/Deadlines.aspx?seriesCode=FSAE) or announced by the organizer, not in the rulebook. An event official assigned as Reviewer (PS.1.2.8) reviews and accepts each submission. A late document in the Tech or Other group costs 20 points for each 24-hour period or part of one. If a Tech-group document (SES, ESO/ESA form, ESF) is never submitted, that is grounds for removing the team entry. If an Other-group document is never submitted, the team is dropped from the Cost, Design or Presentation event and scores zero there. Organizers do not warn a team about a wrong upload, so the team has to keep its own proof of upload. Model state: the 72 PS, Table PS-1 and Table PS-2 paragraphs are in the model but not traced to any element. 21 of them (every Table PS-1 and PS-2 row and the PS.3.4.1 and PS.3.4.2 headings) still need an applicability review. The only related element is the operational activity \'FSAE2027:process Prepare and document competition entry\', owned by Team personnel, with no exchanges or links. The penalty numbers sit in the Table PS-2 paragraphs as unreviewed source values. The 2027 SES, ESO/ESA and Cost Addendum templates and the 2027 ESF and EV inspection forms are not in this repository yet; download them from the Event Website.','derive':['TABLE-PS-1:p001','TABLE-PS-2:p001'],'satisfy':['OA|OperationalActivity|FSAE2027:process Prepare and document competition entry'],'attributes':['submission_id':'GEN','submission_governing_rules':'["PS.1.1.1-PS.1.1.2: every document is due by the deadlines and procedures the Event Website or the organizer publishes","PS.1.2.1-PS.1.2.8: meaning of submission date, due date, cancellation date, late, not submitted (wrong format or largely incomplete counts), days late rounded up, removal grounds and Reviewer","PS.2.1, PS.2.2, PS.2.2.1-PS.2.2.4: upload through the team\'s Event Website account; Table PS-1 templates used unchanged; one PDF or XLSX file per submission","PS.3.1.1-PS.3.1.4: the team confirms its own uploads; free replacement before the due date; a revision request can set a new deadline; no warning for a wrong upload","PS.3.2.1-PS.3.2.3: late penalties per Table PS-2, plus further penalties for missing or poorly reviewed documents at official discretion","PS.3.3.1-PS.3.3.2: an entry can be removed for a missing grounds-for-removal document, no reply to the Reviewer or organizer, or at organizer discretion; notice is given and fees are not refunded","PS.3.4.1-PS.3.4.2, IC.4.2: IC-only cases (ETC forms, fuel type); not applicable to this electric car","TABLE-PS-1:p001, TABLE-PS-2:p001: the list of documents with format, template and penalty group, and the penalty per group","AD.1.1-AD.1.3: events may post local rule variations; teams follow official announcements; English is accepted","AD.2.1, AD.2.1.1-AD.2.1.4, AD.2.2: the Event Website and its Series Resources, the team account, the Team Captain, who may upload, and how to reach the organizer","AD.3.7, AD.4.1: student career profiles and the registration roster deadline","AD.5.1.3: the Faculty Advisor must not write team documents or presentations","AD.5.2.2, AD.5.3.2: ESO training and ESA experience go on the ESO/ESA form","AD.6.1, AD.6.2.1-AD.6.2.2, AD.6.3.1-AD.6.3.2, AD.6.4: registration details, fees, waitlist deadlines and withdrawal","GR.4.2.3, GR.4.5.1: documents incorporated by reference count as rules; follow the latest rules issue","GR.7.1, GR.7.2.1-GR.7.2.3, GR.7.3: rules questions: scope, required content, response time, where to send them, and that answers may be published","IN.5.1, IN.6.1: the ESF with datasheets and the electronic SES are brought to inspection","EV.2.1.1, EV.2.1.3, EV.2.2, F.2.2.1-F.2.2.2: ESF and SES are required on the given format with PS penalties; SES reviewer comments must be closed","S.2.4.1, S.2.4.3, S.3.4.2, S.3.6, S.3.7.2-S.3.7.3, S.3.15.3, S.3.15.5: presentation, cost report, cost addendum and cost scenario submissions and their PS penalties","S.4.2.3-S.4.2.4, S.4.3.1, S.4.3.3, S.4.4.2, S.4.5: design documents follow PS, use the templates and must show a serious effort"]','submission_format':'PDF or XLSX as Table PS-1 lists','submission_penalty_group':'none','submission_status':'not_started','submission_due':'TBD','submission_cancellation':'TBD']],['identifier':'FSAE2027:SUB:GEN:LOC','parent':'FSAE2027:SUB:GEN','title':'FSAE2027:SUB GEN-LOC Location and access','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'GEN']],['identifier':'FSAE2027:SUB:GEN:DATE','parent':'FSAE2027:SUB:GEN','title':'FSAE2027:SUB GEN-DATE Deadlines and dates','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'GEN']],['identifier':'FSAE2027:SUB:GEN:FMT','parent':'FSAE2027:SUB:GEN','title':'FSAE2027:SUB GEN-FMT Format and templates','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'GEN']],['identifier':'FSAE2027:SUB:GEN:PS1','parent':'FSAE2027:SUB:GEN','title':'FSAE2027:SUB GEN-PS1 Table PS-1 register','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'GEN']],['identifier':'FSAE2027:SUB:GEN:PEN','parent':'FSAE2027:SUB:GEN','title':'FSAE2027:SUB GEN-PEN Penalties and removal','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'GEN']],['identifier':'FSAE2027:SUB:GEN:PROC','parent':'FSAE2027:SUB:GEN','title':'FSAE2027:SUB GEN-PROC Team process evidence','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'GEN']],['identifier':'FSAE2027:SUB:GEN:RQ','parent':'FSAE2027:SUB:GEN','title':'FSAE2027:SUB GEN-RQ Rules questions','text':'','derive':[],'satisfy':[],'attributes':['submission_id':'GEN']]]

// One scan of OA for the two process activities; a missing or repeated name is rejected.
def wanted = folders.collectMany { it.satisfy } as Set
def elements = [:]
def iterator = api.layer('OA').eAllContents()
while (iterator.hasNext()) {
    def element = iterator.next()
    def nameFeature = element.eClass().getEStructuralFeature('name')
    if (nameFeature == null) continue
    def key = 'OA|' + element.eClass().name + '|' + element.eGet(nameFeature)
    if (wanted.contains(key)) {
        assert !elements.containsKey(key): 'Ambiguous model anchor ' + key
        elements[key] = element
    }
}
wanted.each { assert elements.containsKey(it): 'Missing model anchor ' + it }

def created = [:]
api.batch('Create the FSAE 2027 competition submission layer') {
    def module = req.createModule(api.layer('SA'), 'FSAE2027:SUB:module', 'Formula SAE 2027 competition submissions (candidate readiness)')
    created['FSAE2027:SUB:module'] = module
    folders.each { spec ->
        def parent = created[spec.parent]
        assert parent != null: 'Folder parent must be created first: ' + spec.identifier
        def folder = req.createFolder(parent, spec.identifier, spec.title)
        def requirementClass = folder.eClass().getEPackage().getEClassifier('Requirement')
        assert requirementClass != null && requirementClass.isSuperTypeOf(folder.eClass()):
            'A Folder must be a Requirement subtype to carry attributes and links'
        if (spec.text) req.edit(folder, spec.title, spec.text)
        (common + spec.attributes).each { key, value -> req.setAttribute(folder, key, value) }
        spec.derive.each { id ->
            def row = sources['FSAE-2027-V1:' + id]
            assert row != null: 'Missing source paragraph FSAE-2027-V1:' + id
            req.derive(folder, row)
        }
        spec.satisfy.each { key -> req.satisfy(elements[key], folder) }
        created[spec.identifier] = folder
    }
}
assert req.requirements(created['FSAE2027:SUB:module']).isEmpty()
log.info('Submission layer created: ' + (created.size() - 1) + ' folders. Run the 31-import chunks next.')
return [module: 'FSAE2027:SUB:module', folders: created.size() - 1, items_expected: 588]
